package com.payment;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.math.BigDecimal;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

@SpringBootTest
class OrderServiceTest {

    @Autowired
    private OrderService orderService;

    @Test
    void createShouldSucceedWhenAmountIsValid() {
        Order order = new Order("customer-1", new BigDecimal("100.00"));
        Order created = orderService.create(order);

        assertNotNull(created.getId());
        assertEquals("PENDING", created.getStatus());
        assertEquals(new BigDecimal("100.00"), created.getAmount());
    }

    @Test
    void createShouldThrowWhenAmountIsNull() {
        Order order = new Order("customer-2", null);

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class, () -> {
            orderService.create(order);
        });

        assertEquals("orders.amount must not be null", ex.getMessage());
    }
}

