const fs = require('fs');
const result = JSON.parse(fs.readFileSync('/work/output/result.json','utf8'));
const schema = JSON.parse(fs.readFileSync('/work/input/result.schema.json','utf8'));

const errors = [];
const ok = ['SUCCESS','FAILED','NEED_INFO','UNSAFE'];
if (!ok.includes(result.status)) errors.push('invalid status: ' + result.status);
if (!result.summary || result.summary.trim() === '') errors.push('empty summary');
if (!Array.isArray(result.changedFiles)) errors.push('changedFiles not array');
if (result.status === 'SUCCESS' && result.changedFiles.length < 1) errors.push('SUCCESS needs changedFiles >=1');
if (!Array.isArray(result.testCommands)) errors.push('testCommands not array');
const tOk = ['PASSED','FAILED','SKIPPED'];
if (!tOk.includes(result.testStatus)) errors.push('invalid testStatus: ' + result.testStatus);
const rOk = ['LOW','MEDIUM','HIGH'];
if (!rOk.includes(result.riskLevel)) errors.push('invalid riskLevel: ' + result.riskLevel);
if (typeof result.needHumanAction !== 'boolean') errors.push('needHumanAction missing or not boolean');
if (result.status === 'SUCCESS' && (!result.prBody || result.prBody.trim() === '')) errors.push('SUCCESS needs non-empty prBody');
if (result.testStatus !== 'SKIPPED' && result.testCommands.length < 1) errors.push('non-SKIPPED needs testCommands >=1');

if (errors.length > 0) {
  console.log('VALIDATION ERRORS:');
  errors.forEach(e => console.log('  - ' + e));
  process.exit(1);
} else {
  console.log('Schema validation: PASSED');
}
